		endpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		endpoint.createContext("/sparql", this::query);
		endpoint.start();
		proxy = new SPARQLRepository("http://127.0.0.1:" + endpoint.getAddress().getPort() + "/sparql");
