	@Test
	void literalOperandHandlesEveryRoleAndInverseValueQueriesOverHttp() throws Exception {
		String literal = "\"literal\"";
		for (String section : List.of("outgoing", "predicate", "graph")) {
			List<JsonNode> result = call(section, "rows", null, literal, null);
			assertThat(rows(result)).as(section).isEmpty();
			assertThat(metadata(result).path("explore-graph-mode").asText()).isEqualTo("dataset");
		}
		assertThat(rows(call("incoming", "rows", null, literal, null))).hasSize(4);
		assertThat(count("incoming", "default", literal)).isEqualTo("2");
		assertThat(count("incoming", "named", literal)).isEqualTo("2");
		assertThat(rows(call("subClasses", "rows", null, literal, null))).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("urn:test:other"));
		assertThat(count("subClasses", null, literal)).isEqualTo("1");
	}

	@Test
	void namedNilGraphRemainsDistinctFromTheEndpointsDefaultDataset() throws Exception {
		List<JsonNode> result = call("graph", "rows", null, "<" + RDF4J.NIL + ">", null);
		assertThat(rows(result)).singleElement().satisfies(row -> {
			assertThat(row.get(3).path("value").asText()).isEqualTo(RDF4J.NIL.stringValue());
			assertThat(row.get(0).path("value").asText()).isEqualTo("urn:test:resource");
		});
		assertThat(count("graph", null, "<" + RDF4J.NIL + ">")).isEqualTo("1");
	}

	@Test
	void languagePreferencesAreSafelyBoundThroughTheProxy() throws Exception {
		List<JsonNode> result = call("label", "rows", null, "<urn:test:resource>", "fr-CA");
		assertThat(rows(result)).singleElement()
				.satisfies(row -> assertThat(row.get(0).path("value").asText()).isEqualTo("Francais"));
	}

	@Test
	void genericBlankNodeInputReportsUnsupportedIdentity() throws Exception {
		MockHttpServletRequest request = request("incoming", "rows", null, "_:node", null);
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request, response);
		List<JsonNode> records = records(response);
		JsonNode error = records.getLast();
		assertThat(error.path("type").asText()).isEqualTo("error");
		assertThat(error.path("message").asText()).contains("Unsupported blank-node identity");
	}

	@Test
	void largeCountsRemainExactDecimalStringsThroughTheProxy() throws Exception {
		assertThat(count("incoming", "default", "<urn:test:huge>"))
				.isEqualTo("9007199254740993");
	}

	private void query(HttpExchange exchange) throws IOException {
		try (exchange) {
			String parameters = exchange.getRequestURI().getRawQuery();
			if (parameters == null) {
				parameters = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
			}
			String query = null;
			for (String parameter : parameters.split("&")) {
				String[] pair = parameter.split("=", 2);
				if ("query".equals(URLDecoder.decode(pair[0], StandardCharsets.UTF_8)) && pair.length == 2) {
					query = URLDecoder.decode(pair[1], StandardCharsets.UTF_8);
				}
			}
			try (RepositoryConnection connection = store.getConnection()) {
				if (query != null && query.contains("urn:test:huge") && query.contains("COUNT(")) {
					MapBindingSet row = new MapBindingSet();
					row.addBinding("total",
							connection.getValueFactory().createLiteral("9007199254740993", XSD.INTEGER));
					ByteArrayOutputStream bytes = new ByteArrayOutputStream();
					try (TupleQueryResult result = new IteratingTupleQueryResult(List.of("total"), List.of(row))) {
						QueryResultIO.writeTuple(result, TupleQueryResultFormat.JSON, bytes);
					}
					exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
					exchange.sendResponseHeaders(200, bytes.size());
					bytes.writeTo(exchange.getResponseBody());
					return;
				}
				// RDF4J treats rdf4j:nil as its default-context alias even inside a dataset's named-graph list.
				// Represent the generic endpoint's ordinary named rdf4j:nil IRI with another backing-store name,
				// translating the endpoint's input and output while leaving the actual client query unchanged.
				String backendQuery = query.replace("<" + RDF4J.NIL + ">", "<" + physicalNilName + ">");
				TupleQuery prepared = connection.prepareTupleQuery(backendQuery);
				SimpleDataset dataset = new SimpleDataset();
				dataset.addDefaultGraph(RDF4J.NIL);
				dataset.addNamedGraph(physicalNilName);
				dataset.addNamedGraph(named);
				prepared.setDataset(dataset);
				ByteArrayOutputStream bytes = new ByteArrayOutputStream();
				try (TupleQueryResult result = prepared.evaluate()) {
					List<BindingSet> translated = new ArrayList<>();
					while (result.hasNext()) {
						MapBindingSet row = new MapBindingSet();
						for (Binding binding : result.next()) {
							row.addBinding(binding.getName(), physicalNilName.equals(binding.getValue())
									? RDF4J.NIL
									: binding.getValue());
						}
						translated.add(row);
					}
					try (TupleQueryResult exposed = new IteratingTupleQueryResult(result.getBindingNames(),
							translated)) {
						QueryResultIO.writeTuple(exposed, TupleQueryResultFormat.JSON, bytes);
					}
				}
				exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
				exchange.sendResponseHeaders(200, bytes.size());
				bytes.writeTo(exchange.getResponseBody());
			} catch (RuntimeException failure) {
				byte[] message = failure.toString().getBytes(StandardCharsets.UTF_8);
				exchange.sendResponseHeaders(400, message.length);
				exchange.getResponseBody().write(message);
			}
		}
	}

	private String count(String section, String scope, String resource) throws Exception {
		return metadata(call(section, "count", scope, resource, null)).path("explore-count").asText();
	}

	private List<JsonNode> call(String section, String kind, String scope, String resource, String language)
			throws Exception {
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request(section, kind, scope, resource, language), response);
		List<JsonNode> records = records(response);
		assertThat(records.getLast().path("type").asText()).as(response.getContentAsString()).isEqualTo("end");
		return records;
	}

	private static MockHttpServletRequest request(String section, String kind, String scope, String resource,
			String language) {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/explore");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		request.addParameter("section", section);
		request.addParameter("kind", kind);
		request.addParameter("resource", resource);
		if (scope != null) {
			request.addParameter("scope", scope);
		}
		if (language != null) {
			request.addParameter("language", language);
		}
		return request;
	}

	private static List<JsonNode> records(MockHttpServletResponse response) throws IOException {
		return response.getContentAsString().lines().map(JSON::readTree).toList();
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.findFirst()
				.orElseThrow()
				.path("values");
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		List<JsonNode> rows = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(rows::add);
			}
		}
		return rows;
	}
